begin read only;
select jsonb_build_object(
 'defaults',(select jsonb_agg(jsonb_build_object('owner',r.rolname,'schema',coalesce(n.nspname,'GLOBAL'),'beneficiary',coalesce(g.rolname,'PUBLIC'),'grantor',gr.rolname,'privilege_type',a.privilege_type,'is_grantable',a.is_grantable) order by r.rolname,n.nspname,g.rolname,a.privilege_type) from pg_default_acl d join pg_roles r on r.oid=d.defaclrole left join pg_namespace n on n.oid=d.defaclnamespace cross join lateral aclexplode(d.defaclacl) a left join pg_roles g on g.oid=a.grantee left join pg_roles gr on gr.oid=a.grantor where d.defaclobjtype='r' and r.rolname='postgres' and (n.nspname='public' or d.defaclnamespace=0)),
 'matches',(select jsonb_agg(jsonb_build_object('id',m.id,'external_match_id',m.external_match_id,'fingerprint',m.match_fingerprint,'round',m.round_label,'home',m.home_team,'away',m.away_team,'start',m.federation_start_at,'venue',m.venue,'home_score',m.home_score,'away_score',m.away_score,'fetched_at',m.fetched_at,'club_id',c.club_id,'season_id',c.season_id,'federation',c.federation,'competition_id',c.external_competition_id,'competition_name',c.name,'raw_keys',(select jsonb_agg(k) from jsonb_object_keys(m.raw_data) k),'raw_identity',jsonb_build_object('home_team_id',m.raw_data->'home_team_id','away_team_id',m.raw_data->'away_team_id','source_url',m.raw_data->'source_url','report_status',m.raw_data->'report_status','official_status',m.raw_data->'official_status','report_summary',m.raw_data->'report_summary'),'lineups',(select jsonb_agg(z) from(select side,count(*) players,count(player_id) player_ids,count(shirt_number) dorsals,count(*) filter(where is_goalkeeper) goalkeepers from federation_match_lineups where match_id=m.id group by side) z),'entries',(select jsonb_agg(jsonb_build_object('side',mt.side,'entry_id',e.id,'external_team_id',e.external_team_id,'name',e.display_name,'club_team_id',e.club_team_id,'source_url',e.source_url,'raw_keys',(select jsonb_agg(k) from jsonb_object_keys(e.raw_data) k),'roster_count',(select count(*) from federation_team_roster r where r.entry_id=e.id),'roster_with_id',(select count(player_id) from federation_team_roster r where r.entry_id=e.id))) from federation_match_teams mt join federation_team_entries e on e.id=mt.entry_id where mt.match_id=m.id)) ) from federation_matches m join federation_groups fg on fg.id=m.group_id join federation_competitions c on c.id=fg.competition_id where c.federation='RFEP' and (m.external_match_id='35559' or m.id='51894d05-c323-f3e1-8534-fa79e062c448')),
 'source',(select jsonb_agg(jsonb_build_object('pilot_id',s.match_id,'code',s.federation_match_id,'competition',s.competition_id,'season',s.season_id,'url',s.federation_url,'import_status',s.import_status,'last_imported',s.last_imported_at,'last_checked',s.last_checked_at,'official_keys',(select jsonb_agg(k) from jsonb_object_keys(s.official_data) k),'status',p.status,'pilot_home',p.home_team,'pilot_away',p.away_team,'pilot_player_counts',(select jsonb_agg(z) from(select team,count(*) n from pilot_players pp where pp.match_id=p.id group by team) z),'official_events',(select count(*) from pilot_events pe where pe.match_id=p.id),'stats_events',(select count(*) from stats_events se where se.match_id=p.id),'sessions',(select count(*) from stats_sessions ss where ss.match_id=p.id))) from federation_match_sources s join pilot_matches p on p.id=s.match_id where s.federation='RFEP' and s.federation_match_id='35559'),
 'backend_event_insert',has_table_privilege('service_role','public.federation_match_events','INSERT'),
 'ordinary_event_insert',has_table_privilege('authenticated','public.federation_match_events','INSERT'),
 'new_server_installed',to_regprocedure('public.match_mode_access(uuid,text)') is not null
) inspection;
rollback;
begin read only;
select jsonb_build_object('pilot',(select to_jsonb(p) from pilot_matches p where id='18fa0a6e-e5c6-487e-8315-5bc371e22cb1'),'sources',(select jsonb_agg(jsonb_build_object('match_id',s.match_id,'federation',s.federation,'code',s.federation_match_id,'competition',s.competition_id,'season',s.season_id,'url',s.federation_url,'status',s.import_status,'official_keys',(select jsonb_agg(k) from jsonb_object_keys(s.official_data) k),'official_status',s.official_data->'official_status','last_imported',s.last_imported_at)) from federation_match_sources s where s.match_id='18fa0a6e-e5c6-487e-8315-5bc371e22cb1'),'pilot_counts',(select jsonb_agg(z) from(select team,count(*) players from pilot_players where match_id='18fa0a6e-e5c6-487e-8315-5bc371e22cb1' group by team) z),'rival_candidates',(select jsonb_agg(jsonb_build_object('entry_id',e.id,'team_id',e.external_team_id,'name',e.display_name,'competition',c.external_competition_id,'season',s.label,'source_url',e.source_url,'club_external_id',e.raw_data->'club_external_id','roster_count',(select count(*) from federation_team_roster r where r.entry_id=e.id))) from federation_team_entries e join federation_competitions c on c.id=e.competition_id join seasons s on s.id=c.season_id where c.federation='RFEP' and e.external_team_id='3727'),'status_raw',(select jsonb_build_object('result',raw_data->'result','match_id',raw_data->'match_id','report_summary',raw_data->'report_summary') from federation_matches where id='51894d05-c323-f3e1-8534-fa79e062c448'),'server_rpc',to_regprocedure('public.match_mode_access(uuid,uuid)') is not null,'basic_context_table',to_regclass('public.basic_match_contexts') is not null) detail;
rollback;
